//! `cbuild export`: the plan as a CMakeLists.txt or a Makefile, for the tools and people
//! that need one. Output is deterministic: explicit file lists, no globs.

use std::fmt::Write as _;
use std::path::Path;

use anyhow::{Result, bail};

use crate::plan::{Project, TargetKind};

/// First words of every generated file: such a file may be regenerated over.
pub const HEADER: &str = "# Generated by cbuild";

#[derive(Debug, Clone, Copy, PartialEq, Eq, clap::ValueEnum)]
pub enum Format {
    Cmake,
    Make,
}

impl Format {
    pub fn default_file(self) -> &'static str {
        match self {
            Format::Cmake => "CMakeLists.txt",
            Format::Make => "Makefile",
        }
    }

    fn command(self) -> &'static str {
        match self {
            Format::Cmake => "cmake",
            Format::Make => "make",
        }
    }
}

/// The generated file for `project`. `root` is the path from the file's folder back to
/// the project root ("." when the file sits in the root); `origin` says where the plan
/// came from, for the header.
pub fn generate(
    format: Format,
    project: &Project,
    name: &str,
    origin: &str,
    root: &str,
) -> Result<String> {
    let header = format!(
        "{HEADER} {} from {origin}. Regenerate it with `cbuild export {}`.\n",
        env!("CARGO_PKG_VERSION"),
        format.command()
    );
    let body = match format {
        Format::Cmake => cmake(project, name, root)?,
        Format::Make => make(project, root)?,
    };
    Ok(header + &body)
}

/// C standard as CMake spells it: (`C_STANDARD`, GNU extensions on).
fn standard(std: &str) -> (&'static str, bool) {
    let gnu = std.starts_with("gnu");
    let version = match std.trim_start_matches("gnu").trim_start_matches('c') {
        "89" => "90",
        "99" => "99",
        "11" => "11",
        "17" => "17",
        _ => "23",
    };
    (version, gnu)
}

fn path_str(path: &Path) -> String {
    path.to_string_lossy().replace('\\', "/")
}

// ---- CMake -------------------------------------------------------------------------

/// A quoted CMake argument holding `text` literally.
fn cmake_quote(text: &str) -> String {
    let escaped = text
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('$', "\\$")
        .replace(';', "\\;");
    format!("\"{escaped}\"")
}

/// A project path, relative to the project root, as a quoted CMake argument.
fn cmake_path(path: &Path) -> String {
    let quoted = cmake_quote(&path_str(path));
    format!("\"${{ROOT}}/{}", &quoted[1..])
}

fn pkg_variable(dependency: &str) -> String {
    format!("PKG_{}", dependency.to_uppercase().replace('-', "_"))
}

fn cmake(project: &Project, name: &str, root: &str) -> Result<String> {
    let (version, gnu) = standard(&project.std);
    let mut out = String::new();
    writeln!(out, "cmake_minimum_required(VERSION 3.16)")?;
    writeln!(out, "project({name} LANGUAGES C)\n")?;
    writeln!(out, "set(CMAKE_C_STANDARD {version})")?;
    writeln!(out, "set(CMAKE_C_STANDARD_REQUIRED ON)")?;
    writeln!(
        out,
        "set(CMAKE_C_EXTENSIONS {})",
        if gnu { "ON" } else { "OFF" }
    )?;
    writeln!(
        out,
        "if(NOT CMAKE_BUILD_TYPE)\n  set(CMAKE_BUILD_TYPE Debug)\nendif()"
    )?;
    writeln!(
        out,
        "if(CMAKE_C_COMPILER_ID MATCHES \"GNU|Clang\")\n  \
         add_compile_options(-Wall -Werror=implicit-function-declaration)\nendif()\n"
    )?;
    let root = if root == "." {
        String::new()
    } else {
        format!("/{root}")
    };
    writeln!(out, "set(ROOT \"${{CMAKE_CURRENT_SOURCE_DIR}}{root}\")\n")?;

    let packages: Vec<(&String, &String)> = project
        .dependencies
        .iter()
        .filter_map(|(name, dep)| dep.pkg_config.as_ref().map(|package| (name, package)))
        .collect();
    if !packages.is_empty() {
        writeln!(out, "find_package(PkgConfig REQUIRED)")?;
        for (dependency, package) in &packages {
            writeln!(
                out,
                "pkg_check_modules({} REQUIRED IMPORTED_TARGET {})",
                pkg_variable(dependency),
                cmake_quote(package)
            )?;
        }
        out.push('\n');
    }

    for &i in &project.order {
        let target = &project.targets[i];
        let (command, scope) = match target.kind {
            TargetKind::Executable => ("add_executable", "PRIVATE"),
            // Libraries pass their links on to the programs that use them.
            TargetKind::StaticLibrary => ("add_library", "PUBLIC"),
        };
        let kind = if target.kind == TargetKind::StaticLibrary {
            " STATIC"
        } else {
            ""
        };
        writeln!(out, "{command}({}{kind}", target.name)?;
        for source in &target.sources {
            writeln!(out, "  {}", cmake_path(source))?;
        }
        writeln!(out, ")")?;

        if !target.include_public.is_empty() || !target.include_private.is_empty() {
            write!(out, "target_include_directories({}", target.name)?;
            for (visibility, dirs) in [
                ("PUBLIC", &target.include_public),
                ("PRIVATE", &target.include_private),
            ] {
                if !dirs.is_empty() {
                    write!(out, " {visibility}")?;
                    for dir in dirs {
                        write!(out, " {}", cmake_path(dir))?;
                    }
                }
            }
            writeln!(out, ")")?;
        }
        if !target.defines.is_empty() {
            write!(out, "target_compile_definitions({} PRIVATE", target.name)?;
            for (name, value) in &target.defines {
                let define = if value.is_empty() {
                    name.clone()
                } else {
                    format!("{name}={value}")
                };
                write!(out, " {}", cmake_quote(&define))?;
            }
            writeln!(out, ")")?;
        }

        let mut links: Vec<String> = target
            .target_deps
            .iter()
            .map(|&j| project.targets[j].name.clone())
            .collect();
        for dependency in &target.system_deps {
            let dep = &project.dependencies[dependency];
            links.push(match (&dep.link, &dep.pkg_config) {
                (Some(library), _) => cmake_quote(library),
                _ => format!("PkgConfig::{}", pkg_variable(dependency)),
            });
        }
        if !links.is_empty() {
            writeln!(
                out,
                "target_link_libraries({} {scope} {})",
                target.name,
                links.join(" ")
            )?;
        }
        out.push('\n');
    }
    Ok(out)
}

// ---- Make --------------------------------------------------------------------------

/// Make splits on whitespace and gives meaning to `$ # % : '`: paths using them cannot be listed.
fn make_path(path: &Path) -> Result<String> {
    let text = path_str(path);
    if text
        .chars()
        .any(|c| c.is_whitespace() || "$#%:'\"\\".contains(c))
    {
        bail!("`{text}` cannot be written in a Makefile: rename it, or export to CMake instead");
    }
    Ok(text)
}

/// A shell word holding `text` literally, written so make passes it through unchanged.
fn make_shell_word(text: &str) -> String {
    let quoted = format!("'{}'", text.replace('\'', "'\\''"));
    quoted.replace('$', "$$").replace('#', "\\#")
}

fn make(project: &Project, root: &str) -> Result<String> {
    let mut out = String::new();
    writeln!(
        out,
        "#\n#   make              debug build in build/debug/\n#   make RELEASE=1    optimized build in build/release/\n#   make clean\n"
    )?;
    // Relative to this file, wherever make is run from (`make -f path/to/it`).
    writeln!(out, "ROOT := $(dir $(lastword $(MAKEFILE_LIST))){root}")?;
    writeln!(
        out,
        "STD_FLAGS := -std={} -Wall -Werror=implicit-function-declaration -MMD -MP",
        project.std
    )?;
    writeln!(
        out,
        "# Each profile has its own folder, so switching never reuses objects built with other flags.\n\
         ifdef RELEASE\nPROFILE_FLAGS := -O2 -DNDEBUG\nBUILD ?= build/release\n\
         else\nPROFILE_FLAGS := -O0 -g\nBUILD ?= build/debug\nendif\n"
    )?;

    let output = |i: usize| {
        let target = &project.targets[i];
        match target.kind {
            TargetKind::Executable => format!("$(BUILD)/{}", target.name),
            TargetKind::StaticLibrary => format!("$(BUILD)/lib{}.a", target.name),
        }
    };
    let all: Vec<String> = project.order.iter().map(|&i| output(i)).collect();
    writeln!(out, "all: {}\n", all.join(" "))?;

    let mut objects = Vec::new();
    for &i in &project.order {
        let target = &project.targets[i];
        let name = &target.name;
        let kind = match target.kind {
            TargetKind::Executable => "program",
            TargetKind::StaticLibrary => "static library",
        };
        writeln!(out, "# {name}: {kind}")?;

        let sources: Vec<String> = target
            .sources
            .iter()
            .map(|s| make_path(s).map(|s| format!("$(ROOT)/{s}")))
            .collect::<Result<_>>()?;
        writeln!(out, "{name}_SRCS := {}", sources.join(" "))?;
        writeln!(
            out,
            "{name}_OBJS := $(patsubst $(ROOT)/%.c,$(BUILD)/obj/{name}/%.o,$({name}_SRCS))"
        )?;

        let mut flags = Vec::new();
        for dir in project.includes(i) {
            flags.push(format!("-I$(ROOT)/{}", make_path(&dir)?));
        }
        for (define, value) in &target.defines {
            let define = if value.is_empty() {
                format!("-D{define}")
            } else {
                format!("-D{define}={value}")
            };
            flags.push(make_shell_word(&define));
        }
        let mut libraries = Vec::new();
        for dependency in project.system_deps(i) {
            let dep = &project.dependencies[dependency];
            match (&dep.link, &dep.pkg_config) {
                (Some(library), _) => libraries.push(format!("-l{library}")),
                (_, Some(package)) => {
                    let package = make_shell_word(package);
                    flags.push(format!("$(shell pkg-config --cflags {package})"));
                    libraries.push(format!("$(shell pkg-config --libs {package})"));
                }
                _ => {}
            }
        }
        writeln!(out, "{name}_FLAGS := {}", flags.join(" "))?;
        writeln!(out, "$(BUILD)/obj/{name}/%.o: $(ROOT)/%.c")?;
        writeln!(out, "\t@mkdir -p $(@D)")?;
        writeln!(
            out,
            "\t$(CC) $(STD_FLAGS) $(PROFILE_FLAGS) $({name}_FLAGS) $(CFLAGS) -c $< -o $@"
        )?;

        match target.kind {
            TargetKind::StaticLibrary => {
                writeln!(out, "{}: $({name}_OBJS)", output(i))?;
                writeln!(out, "\t@mkdir -p $(@D)")?;
                writeln!(out, "\t@rm -f $@")?;
                writeln!(out, "\t$(AR) rcs $@ $^")?;
            }
            TargetKind::Executable => {
                let linked: Vec<String> = project.link_closure(i).into_iter().map(output).collect();
                let linked = linked.join(" ");
                writeln!(out, "{}: $({name}_OBJS) {linked}", output(i))?;
                writeln!(out, "\t@mkdir -p $(@D)")?;
                writeln!(
                    out,
                    "\t$(CC) $({name}_OBJS) {linked} {} $(LDFLAGS) -o $@",
                    libraries.join(" ")
                )?;
            }
        }
        out.push('\n');
        objects.push(format!("$({name}_OBJS:.o=.d)"));
    }

    // Both profiles go, but never the whole build/ folder: it may hold other builds (CMake's).
    writeln!(
        out,
        "clean:\n\trm -rf $(BUILD) build/debug build/release\n\t@rmdir build 2>/dev/null || true\n"
    )?;
    writeln!(out, ".PHONY: all clean")?;
    writeln!(out, "-include {}", objects.join(" "))?;
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn cmake_arguments_are_escaped() {
        assert_eq!(cmake_quote("VERSION=\"1.2\""), "\"VERSION=\\\"1.2\\\"\"");
        assert_eq!(cmake_quote("a;b$c"), "\"a\\;b\\$c\"");
        assert_eq!(
            cmake_path(Path::new("src/main.c")),
            "\"${ROOT}/src/main.c\""
        );
    }

    #[test]
    fn make_words_survive_make_and_the_shell() {
        assert_eq!(make_shell_word("-DVERSION=\"1.2\""), "'-DVERSION=\"1.2\"'");
        assert_eq!(make_shell_word("-DPRICE=$5#off"), "'-DPRICE=$$5\\#off'");
        assert_eq!(make_shell_word("-DQUOTE=it's"), "'-DQUOTE=it'\\''s'");
        assert!(make_path(Path::new("my dir/a.c")).is_err());
    }

    #[test]
    fn c_standards_map_to_cmake() {
        assert_eq!(standard("gnu17"), ("17", true));
        assert_eq!(standard("c89"), ("90", false));
        assert_eq!(standard("c11"), ("11", false));
    }
}
